import * as T from 'three';
import {transformSnapshot,copyTransform} from './manipulation.js?v=20261025-release1';

export function quickTransform(start,camera,mode,dx,dy,units=1,precision=1,snap=false){
 const result={position:start.position.clone(),quaternion:start.quaternion.clone(),scale:start.scale.clone()},q=camera.quaternion,right=new T.Vector3(1,0,0).applyQuaternion(q),up=new T.Vector3(0,1,0).applyQuaternion(q),forward=new T.Vector3(0,0,1).applyQuaternion(q);dx*=precision;dy*=precision;
 if(mode==='screen'||mode==='ground'){if(mode==='ground'){right.y=0;right.normalize();up.copy(forward);up.y=0;up.normalize();}result.position.addScaledVector(right,dx*units).addScaledVector(up,(mode==='ground'?dy:-dy)*units);if(snap)for(const a of ['x','y','z'])result.position[a]=Math.round(result.position[a]*10)/10;}
 else{let x=dx*.01,y=dy*.01;if(snap){const step=Math.PI/36;x=Math.round(x/step)*step;y=Math.round(y/step)*step;}const turn=new T.Quaternion();if(mode==='yaw')turn.setFromAxisAngle(new T.Vector3(0,1,0),x);else if(mode==='roll')turn.setFromAxisAngle(forward,-x);else turn.setFromAxisAngle(up,x).multiply(new T.Quaternion().setFromAxisAngle(right,y));result.quaternion.premultiply(turn).normalize();}return result;
}
export function setupQuickTransform(gizmo){
 const e=gizmo.editor,bar=document.createElement('div');bar.className='scene-quick-transform';bar.setAttribute('aria-label','인물 빠른 배치');bar.innerHTML=[['screen','✥ 화면 이동'],['ground','↔ 바닥 이동'],['yaw','⟳ 좌우 회전'],['roll','◴ 기울이기'],['orbit','↻ 자유 회전']].map(([key,name])=>`<button data-quick-transform="${key}" title="누른 채 드래그 · Shift 미세 조정 · Ctrl 스냅 · Esc 취소">${name}</button>`).join('');gizmo.toolbar.querySelector('.gizmo-modes').after(bar);
 const label=document.createElement('label');label.className='scene-space';label.innerHTML='축 기준 <select aria-label="3D 조작 축 기준"><option value="world">월드 · 공간 축</option><option value="local">로컬 · 인물 축</option></select><small>버튼을 드래그해서 배치</small>';bar.after(label);label.querySelector('select').onchange=ev=>{gizmo.space=ev.target.value;gizmo.transform.setSpace(gizmo.space);e.invalidate();};let drag=null;
 function finish(cancel=false){if(!drag)return;const d=drag;drag=null;gizmo.quickDragging=false;e.controls.enabled=true;if(cancel){e.state.people[d.index]=d.person;e.updatePerson();}gizmo.sync();e.controlsUI();e.transformCommit=!cancel;e.queueLive();e.flush();gizmo.dragFinished=performance.now();}
 bar.onpointerdown=ev=>{const button=ev.target.closest('[data-quick-transform]'),p=e.state.people[e.index];if(!button||!p||ev.button!==0)return;ev.preventDefault();e.movement?.stop();gizmo.part='whole';document.getElementById('jointSelect').value='whole';gizmo.setMode(['screen','ground'].includes(button.dataset.quickTransform)?'translate':'rotate');gizmo.sync();const distance=e.camera.position.distanceTo(gizmo.proxy.position),height=e.renderer.domElement.clientHeight||400,units=2*Math.tan(e.camera.fov*Math.PI/360)*distance/height;drag={index:e.index,person:structuredClone(p),start:transformSnapshot(gizmo.proxy),x:ev.clientX,y:ev.clientY,mode:button.dataset.quickTransform,units,dx:0,dy:0};gizmo.quickDragging=true;e.controls.enabled=false;button.setPointerCapture(ev.pointerId);};
 bar.onpointermove=ev=>{if(!drag)return;const speed=ev.shiftKey?.1:1;drag.dx+=(ev.clientX-drag.x)*speed;drag.dy+=(ev.clientY-drag.y)*speed;drag.x=ev.clientX;drag.y=ev.clientY;copyTransform(gizmo.proxy,quickTransform(drag.start,e.camera,drag.mode,drag.dx,drag.dy,drag.units,1,ev.ctrlKey));gizmo.toPerson();e.invalidate();};
 bar.onpointerup=()=>finish();bar.onpointercancel=()=>finish(true);bar.addEventListener('lostpointercapture',()=>{if(drag)finish(true);});document.getElementById('sceneDialog').addEventListener('keydown',ev=>{if(drag&&ev.key==='Escape'){ev.preventDefault();ev.stopImmediatePropagation();finish(true);}},true);window.addEventListener('blur',()=>finish(true));return {cancel:()=>finish(true)};
}
